import{_ as i}from"./exploration-49b36a5e.js";import{j as d,k as r,o as f,c as o,a,u,U as l,p as v,q as p,_ as c}from"./index-d747ed81.js";const m="/DungeonOfAsunVue/assets/Riannedos-0f7022fe.png",h="/DungeonOfAsunVue/assets/Lorus-eedc6341.png",b="/DungeonOfAsunVue/assets/Humans-2206408b.png",g="/DungeonOfAsunVue/assets/Neien-6901ca09.png",n=e=>(v("data-v-5f664f03"),e=e(),p(),e),_={class:"visible"},x=l('<div class="header" data-v-5f664f03><h1 data-v-5f664f03>L&#39;Histoire générale</h1><h2 data-v-5f664f03>L&#39;Aube d&#39;Asun : Une Épopée à travers les<span data-v-5f664f03> Âges </span></h2></div><div class="row" data-v-5f664f03><article data-v-5f664f03><div class="title-section" data-v-5f664f03><h2 data-v-5f664f03>La genèse</h2><h3 data-v-5f664f03>Introduction</h3></div><p data-v-5f664f03> Au commencement, il n&#39;y avait que le Néant, un vide infini habité par des entités éternelles connues sous le nom d&#39;<span data-v-5f664f03>Êtres du Néant</span>. Parmi eux, un être singulier ressentit le besoin de créer, de façonner quelque chose de nouveau. Ce fut <span data-v-5f664f03>Riannedos</span>, le dragon primordial, qui, par un acte de volonté divine, enveloppa son propre corps pour donner naissance à un monde. Ainsi naquit <span data-v-5f664f03>Asun</span>, un berceau façonné par le Temps et protégé par les écailles cosmiques de son créateur.<br data-v-5f664f03><br data-v-5f664f03> Riannedos n&#39;était pas seul longtemps. D&#39;autres Êtres du Néant vinrent à lui, fascinés par sa création. <span data-v-5f664f03>Quaara</span>, déesse de la nature, et son frère <span data-v-5f664f03>Gusius</span>, dieu des animaux, insufflèrent la vie dans ce monde, donnant naissance à des forêts luxuriantes, des créatures majestueuses, et des océans sans fin.<br data-v-5f664f03><br data-v-5f664f03><span data-v-5f664f03>Eone</span>, dieu des savoirs, offrit la connaissance aux premiers habitants : les Dragons. Ces derniers régnèrent en maîtres sur Asun, forts de leur sagesse et de leur puissance. Mais la vie éternelle s&#39;avéra être un fardeau. C&#39;est alors qu&#39;intervint <span data-v-5f664f03>Fauscht</span>, dieu de la mort, qui offrit aux dragons le don de la mortalité, libérant ainsi leur essence de l&#39;ennui de l&#39;éternité.<br data-v-5f664f03><br data-v-5f664f03> Enfin, <span data-v-5f664f03>Théomis</span>, dieu de l&#39;ordre, descendit avec ses enfants pour façonner les <span data-v-5f664f03>Hommes</span>, destinés à vivre sous la domination des Dragons, afin d&#39;apprendre et de prospérer sous leur tutelle divine. </p></article><div class="image" data-v-5f664f03><img src="'+m+'" data-v-5f664f03><div class="filter" data-v-5f664f03></div></div></div><div class="row-reverse" data-v-5f664f03><article data-v-5f664f03><div class="title-section" data-v-5f664f03><h2 data-v-5f664f03>L&#39;ère des Hommes</h2><h3 data-v-5f664f03>Royaume Saint de Lorus</h3></div><p data-v-5f664f03> Le fragile équilibre fut rompu lorsque Théomis confia à son fils, <span data-v-5f664f03>Edes</span>, la mission de protéger les Hommes. Animé par une soif de justice intransigeante, Edes mena une croisade impitoyable contre les Dragons, les décimant presque jusqu&#39;à leur extinction. Seuls quelques survivants se mêlèrent aux hommes, donnant naissance aux <span data-v-5f664f03>Drakèides</span>, héritiers d&#39;un sang mêlé de gloire et de malédiction.<br data-v-5f664f03><br data-v-5f664f03> Après sa victoire, Edes fonda le <span data-v-5f664f03>Royaume Saint de Lorus</span>, un empire théocratique où l&#39;homme dominait, glorifiant Théomis et Edes comme des divinités suprêmes. Ce royaume devint le symbole de la puissance humaine, mais aussi de l&#39;arrogance des mortels face aux autres races bénies par les dieux.<br data-v-5f664f03><br data-v-5f664f03> La politique expansionniste et belliqueuse de Lorus entraîna la naissance de nouveaux royaumes : <span data-v-5f664f03>L&#39;Empire de Koven</span>, dominé par des orcs, ennemis jurés de Lorus. <span data-v-5f664f03>Le Royaume de Trésabia</span>, havre de paix et de diplomatie. <span data-v-5f664f03>La Dynastie Owrilia</span>, issue de l&#39;union des dragons survivants et des habitants pacifistes de Trésabia, fondée sur des principes d&#39;équilibre et de coexistence. </p></article><div class="image-left" data-v-5f664f03><img src="'+h+'" data-v-5f664f03><div class="filter-left" data-v-5f664f03></div></div></div><div class="row" data-v-5f664f03><article data-v-5f664f03><div class="title-section" data-v-5f664f03><h2 data-v-5f664f03>Le nouveau Monde</h2><h3 data-v-5f664f03>Exploration Millénaire</h3></div><p data-v-5f664f03> Au-delà des frontières connues d&#39;Asun s&#39;étend un territoire inexploré, appelé le <span data-v-5f664f03>Nouveau Monde</span>. Pendant des millénaires, des peuples divers s&#39;y aventurèrent, cherchant richesse, savoir, et rédemption. Ce fut un terrain d&#39;expansion, mais aussi de conflits, car les vieilles croyances s&#39;effritaient. De nouveaux dieux, de nouvelles races, et de nouveaux empires virent le jour.<br data-v-5f664f03><br data-v-5f664f03> C&#39;est dans ce chaos qu&#39;apparurent les <span data-v-5f664f03>Vampires</span>, êtres du Void, avatars de vengeance contre Théomis et sa lignée. Rejetant les doctrines du Royaume Saint de Lorus, ils cherchèrent à corrompre l&#39;œuvre des dieux et à renverser l&#39;ordre établi. </p></article><div class="image" data-v-5f664f03><img src="'+i+'" style="transform:scaleX(-1);" data-v-5f664f03><div class="filter" data-v-5f664f03></div></div></div><div class="row-reverse" data-v-5f664f03><article data-v-5f664f03><div class="title-section" data-v-5f664f03><h2 data-v-5f664f03>L&#39;Empire</h2><h3 data-v-5f664f03>Montée de l&#39;Empire</h3></div><p data-v-5f664f03> Sur ce continent fracturé, un homme parvint à unir des peuples disparates sous une seule bannière : <span data-v-5f664f03>l&#39;Empire Cytanique</span>. Bien qu&#39;il n&#39;ait jamais dominé la totalité du monde, il s&#39;imposa comme la plus grande force militaire, culturelle, et politique d&#39;Asun. Il établit des cités prospères, des routes commerciales florissantes, et des institutions stables, surpassant même la puissance du Saint Royaume de Lorus.<br data-v-5f664f03><br data-v-5f664f03> Cependant, l&#39;ombre d&#39;un ancien pouvoir plane encore sur Asun... </p></article><div class="image-left" data-v-5f664f03><img src="'+b+'" data-v-5f664f03><div class="filter-left" data-v-5f664f03></div></div></div><div class="row" data-v-5f664f03><article data-v-5f664f03><div class="title-section" data-v-5f664f03><h2 data-v-5f664f03>Le secret millénaires</h2><h3 data-v-5f664f03>Reliques de Neien</h3></div><p data-v-5f664f03> Parmi tous les dieux, <span data-v-5f664f03>Neien</span> fut le plus puissant. Anciennement dieu de la miséricorde, il fut trahi, banni, et enfermé par ses pairs au fin fond du <span data-v-5f664f03>Donjon d&#39;Asun</span>, connu sous le nom des <span data-v-5f664f03>Enfers</span>. Son essence fut fracturée et dispersée à travers Asun sous forme de <span data-v-5f664f03>Reliques</span>.<br data-v-5f664f03><br data-v-5f664f03> Ces artefacts, imprégnés de fragments de sa divinité, offrent à quiconque les détient un pouvoir égal à celui d’un dieu. Leur influence est un appel irrésistible pour les aventuriers, les rois, et même les dieux eux-mêmes.<br data-v-5f664f03><br data-v-5f664f03> L&#39;histoire d&#39;Asun est celle d&#39;un monde façonné par des dieux, mais peut-être, un jour, sera-t-il façonné par des mortels.<br data-v-5f664f03><br data-v-5f664f03><i data-v-5f664f03>Bienvenue dans le monde d&#39;Asun, où chaque choix peut façonner le destin des dieux et des hommes.</i></p></article><div class="image" data-v-5f664f03><img src="'+g+'" data-v-5f664f03><div class="filter" data-v-5f664f03></div></div></div>',6),q={class:"banner"},A=n(()=>a("h3",null,"Ecrivez l'histoire",-1)),L=n(()=>a("div",{class:"banner-img"},null,-1)),y=d({__name:"StoryView",setup(e){const t=r();return(E,s)=>(f(),o("div",_,[x,a("div",q,[A,a("button",{onClick:s[0]||(s[0]=S=>u(t).push({path:"/Rules/creation"}))},"Commencer"),L])]))}});const D=c(y,[["__scopeId","data-v-5f664f03"]]);export{D as default};
